window.__ATLAS_SNAPSHOT__["search_text"]["records"][5215]={"row_id":"G-B-027","table":"compliance","country_id":"VNM","trigram":"汽车专属法源待核实 整车进口商、制造商或软件提供者可能需要关注型式认证、软件更新和网络安全；车载语音功能是否在规则范围内须单独判断。 读取状态：有限检索未找到或原文受限。已查：https://congbao.chinhphu.vn/van-ban/luat-so-134-2025-qh15-468694.htm; https://datafiles.chinhphu.vn/cpp/files/vbpq/2026/4/142-2026-ndcp.signed.pdf; https://baochinhphu.vn/danh-muc-he-thong-tri-tue-nhan-tao-co-rui-ro-cao-102260702152849868.htm; https://vanban.chinhphu.vn/?classid=1&docid=214590&pageid=27160&typegroup=。检索关键词：vehicle cybersecurity / software updates / type approval（车辆网络安全、软件更新、型式认证）；已查上述官方法库或政策入口，尚未确认可用于本卡的汽车数据/软件专属文本。国际标准及别国规则不能代替本国适用证明。“未找到”不是无要求；尚未形成该层的可执行法律清单。","words":["汽车专属法源待核实","整车进口商","制造商或软件提供者可能需要关注型式认证","软件更新和网络安全","车载语音功能是否在规则范围内须单独判断","读取状态","有限检索未找到或原文受限","已查","https","congbao","chinhphu","vn","van","ban","luat","so","134","2025","qh15","468694","htm","https","datafiles","chinhphu","vn","cpp","files","vbpq","2026","4","142","2026","ndcp","signed","pdf","https","baochinhphu","vn","danh","muc","he","thong","tri","tue","nhan","tao","co","rui","ro","cao","102260702152849868","htm","https","vanban","chinhphu","vn","classid","1","docid","214590","pageid","27160","typegroup","检索关键词","vehicle","cybersecurity","software","updates","type","approval","车辆网络安全","软件更新","型式认证","已查上述官方法库或政策入口","尚未确认可用于本卡的汽车数据","软件专属文本","国际标准及别国规则不能代替本国适用证明","未找到","不是无要求","尚未形成该层的可执行法律清单"]};
